/* UI and in-memory navigation adapted from the existing Phase 3 app. No persistence or transmission. */
(() => {
'use strict';
const V=PiraV6,C=PiraV6Content,D=PiraDiagnosis,app=document.getElementById('app'),esc=D.escapeHtml;
const audience=V.audience(new URLSearchParams(location.search).get('audience'));
const audienceLabels={PIRA_UNION:'PIRA組合向け',MEMBER_COMPANY:'組合所属企業向け',ATLIB_GENERAL:'atLIB一般企業向け'};
document.querySelector('.brand small').textContent=audienceLabels[audience];
const dialog=document.getElementById('info-dialog');document.getElementById('close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
const showInfo=html=>{document.getElementById('dialog-content').innerHTML=html;dialog.showModal();};
let state={screen:'start',index:0,draft:{},result:null,report:null,sample:false},personalSession=null,sampleSession=null;
const copy=x=>JSON.parse(JSON.stringify(x));
function remember(){if(state.screen==='start'||!Object.keys(state.draft).length)return;if(state.sample)sampleSession=copy(state);else personalSession=copy(state);}
function focusPage(){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function home(){remember();state.screen='start';render();focusPage();}
document.getElementById('service-home').onclick=e=>{e.preventDefault();home();};
function start(){state=personalSession?copy(personalSession):{screen:'question',index:0,draft:{},result:null,report:null,sample:false};state.screen=state.result?'result':'question';render();focusPage();}
function newAnswer(){showInfo('<h2>新しく回答をはじめますか</h2><p>現在の自分の回答を消して、最初から回答します。</p><div class="dialog-actions"><button id="keep" class="btn secondary">今の回答を残す</button><button id="reset" class="btn">新しく回答する</button></div>');document.getElementById('keep').onclick=()=>dialog.close();document.getElementById('reset').onclick=()=>{personalSession=null;dialog.close();start();};document.getElementById('keep').focus();}
const samples=[['ALL_READY','全実施済み'],['ALL_UNKNOWN','全不明'],['MIXED','実施状況混在'],['MANY_NA','対象外多数'],['MAJOR_READY','主要3テーマ実施済み・他未整備'],['DELEGATED','委託先任せ'],['TWO_TARGETS','対象2テーマのみ']];
function sample(id){if(state.screen!=='start')remember();state={screen:'question',index:0,draft:Object.fromEntries(PiraV6Demos[id].answers.map(a=>[a.questionId,a.answerId])),result:null,report:null,sample:true};complete();}
function landing(){
 app.innerHTML='<div class="landing"><div class="hero"><section><p class="eyebrow">'+esc(audienceLabels[audience])+'</p><h1>情報管理<br>セルフチェック</h1><p class="lead">日々の仕事に沿って、情報管理の状況を整理。</p><div class="trust"><span>全8問</span><span>すべて選択式</span><span>登録・送信なし</span></div><div class="hero-actions"><button id="start" class="btn accent">'+(personalSession?(personalSession.result?'今のレポートへ戻る':'回答を続ける'):'セルフチェックをはじめる')+' →</button></div>'+(personalSession?'<button id="new-answer" class="btn secondary">新しく回答する</button>':'')+(sampleSession?'<button id="resume-sample" class="btn secondary">直前のサンプルへ戻る</button>':'')+'<p class="small">点数や危険度で評価しません。「分からない」も有効な回答です。</p></section><aside class="preview"><p class="eyebrow">回答のあとに得られるもの</p><h2>情報保護に関する<br>基本的な知識</h2><div class="preview-row"><b>01</b><div><strong>回答に応じた重点3テーマ</strong></div></div><div class="preview-row"><b>02</b><div><strong>全8テーマの基礎知識集</strong></div></div><div class="preview-row"><b>03</b><div><strong>日常業務で使える実務資料</strong></div></div></aside></div><section class="demo-section"><div class="section-line"><h2>サンプルを見る</h2><p class="small">架空の回答例です。実在団体の評価ではありません。</p></div><div class="demo-grid">'+samples.slice(0,4).map(([id,t],i)=>'<button class="demo-card" data-demo="'+id+'"><span>回答例 '+String(i+1).padStart(2,'0')+'</span><strong>'+esc(t)+' ↗</strong></button>').join('')+'</div><details class="small"><summary>その他の検証用サンプル</summary><p>'+samples.slice(4).map(([id,t])=>'<button class="btn secondary" data-demo="'+id+'">'+esc(t)+'</button>').join(' ')+'</p></details></section></div>';
 document.getElementById('start').onclick=start;document.getElementById('new-answer')?.addEventListener('click',newAnswer);document.getElementById('resume-sample')?.addEventListener('click',()=>{remember();state=copy(sampleSession);render();focusPage();});app.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>sample(b.dataset.demo));
}
function question(){
 const q=V.questions[state.index],value=state.draft[q.id],count=Object.keys(state.draft).length;
 app.innerHTML='<div class="workbench"><aside class="rail"><p class="eyebrow">情報管理セルフチェック</p><ol>'+V.questions.map((x,i)=>'<li><button data-jump="'+i+'" class="'+(i===state.index?'current':state.draft[x.id]?'done':'')+'"><i>'+(state.draft[x.id]?'✓':i+1)+'</i>'+esc(C.themes[x.id].title)+'</button></li>').join('')+'</ol><button id="home" class="btn secondary">トップページへ戻る</button></aside><section class="question-panel"><div class="question-return"><button id="question-home" class="link-button">トップページへ戻る</button></div><div class="progress-label"><span>'+(state.index+1)+' / 8</span><span>'+count+'問 回答済み</span></div><div class="progress-track"><span id="progress-fill"></span></div><h1>'+esc(q.text)+'</h1><div class="options" role="group" aria-label="回答の選択肢">'+q.options.map(o=>'<button class="option '+(value===o.id?'selected':'')+'" data-value="'+o.id+'" aria-pressed="'+(value===o.id)+'">'+esc(o.label)+'</button>').join('')+'</div><div class="question-actions"><button id="back" class="btn secondary">'+(state.index?'前の質問へ':'トップページへ戻る')+'</button><button id="next" class="btn accent" '+(value?'':'disabled')+'>'+(state.index===7?'結果とレポートを見る':'次の質問へ')+' →</button></div><p class="small">あとから戻って、回答を修正できます。</p></section></div>';
 document.getElementById('progress-fill').style.width=(count/8*100)+'%';document.getElementById('home').onclick=home;document.getElementById('question-home').onclick=home;
 app.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{state.draft[q.id]=b.dataset.value;state.result=null;state.report=null;question();app.querySelector('[data-value="'+b.dataset.value+'"]').focus({preventScroll:true});});
 app.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{state.index=Number(b.dataset.jump);question();focusPage();});
 document.getElementById('back').onclick=()=>{if(!state.index)home();else{state.index--;question();focusPage();}};
 document.getElementById('next').onclick=()=>{if(state.index===7)complete();else{state.index++;question();focusPage();}};
}
function complete(){try{state.result=V.evaluate(V.envelope(state.draft));state.report=V.report(state.result,audience);state.screen='result';render();focusPage();}catch(e){showInfo('<h2>'+esc(e.message)+'</h2>');}}
function blocks(bs){return bs.map(b=>b.kind==='heading'?'<h3 data-report-text>'+esc(b.text)+'</h3>':'<p data-report-text class="'+(b.kind==='source'?'source-copy':b.kind==='check'?'check-copy':'')+'">'+esc(b.text)+'</p>').join('');}
const pdfUrls=[];window.addEventListener('pagehide',()=>pdfUrls.forEach(url=>URL.revokeObjectURL(url)));
function result(){
 const r=state.result,rep=state.report;
 app.innerHTML='<div class="report-shell phase3 v6"><div class="report-toolbar"><button id="report-home" class="btn secondary">トップページへ戻る</button><button id="edit" class="btn secondary">回答を見直す</button><button id="download" class="btn secondary">回答・結果の記録</button><button id="view-pdf" class="btn accent">PDFで表示</button></div><header class="report-cover"><span class="badge">'+(state.sample?'架空の回答によるサンプル':'ご回答に基づくセルフチェック')+'</span><h1>'+esc(rep.title)+'</h1><p data-report-text>'+esc(rep.disclaimer)+'</p></header><nav class="report-nav">'+rep.sections.map((s,i)=>'<a href="#report-s'+(i+1)+'">'+String(i+1).padStart(2,'0')+' '+esc(s.title)+'</a>').join('')+'</nav>'+rep.sections.map((s,i)=>{
 let body=blocks(s.blocks);
 if(i===2)body=rep.themes.map(t=>'<article class="theme-card" data-theme="'+t.id+'"><h3 data-report-text>'+esc(t.title)+'</h3>'+blocks(t.blocks)+'</article>').join('')+'<p><a href="v6-knowledge.html" target="_blank" rel="noopener">情報保護に関するその他の基礎知識集 →</a></p>';
 if(i===3)body=rep.resources.map(m=>'<article class="resource-card" data-material="'+m.id+'">'+blocks(s.blocks.filter(b=>b.id.startsWith(m.id+'-')))+'<div class="material-links">'+m.files.map(f=>'<a class="btn secondary" target="_blank" rel="noopener" href="'+esc(f.href)+'">'+esc(f.label)+'</a>').join('')+'</div></article>').join('')+'<p><a href="v6-materials.html" target="_blank" rel="noopener">全5種類の実務資料を見る →</a></p>';
 return '<section id="report-s'+(i+1)+'" class="report-section" data-section="'+s.key+'"><div class="section-heading"><span class="num">'+String(i+1).padStart(2,'0')+'</span><h2 data-report-text>'+esc(s.title)+'</h2></div>'+body+'</section>';
 }).join('')+rep.supplements.map(s=>'<section class="report-section" data-supplement="'+s.key+'"><h2 data-report-text>'+esc(s.title)+'</h2>'+blocks(s.blocks)+'</section>').join('')+'<div class="version-info"><p data-report-text>'+esc(rep.versionText)+'</p></div><section class="feedback-panel"><h2>このレポートは役立ちましたか</h2><p>回答は任意です。レポートやPDFは、この回答に関係なくご利用いただけます。</p><p class="small">試作品では選択内容をこの画面内に表示するだけで、送信・保存はしません。</p><div class="feedback-options">'+['役立った','どちらともいえない','改善してほしい'].map((text,i)=>'<label><input type="radio" name="report-feedback" value="'+i+'"> '+text+'</label>').join('')+'</div><p class="feedback-status" role="status"></p></section></div>';
 document.getElementById('report-home').onclick=home;document.getElementById('edit').onclick=()=>{state.screen='question';state.index=0;state.result=null;state.report=null;question();focusPage();};
 app.querySelectorAll('[name="report-feedback"]').forEach(el=>el.onchange=()=>{app.querySelector('.feedback-status').textContent='選択しました（この画面内のみ・未送信）。';});
 document.getElementById('download').onclick=async()=>{const snap=await V.snapshot(V.envelope(state.draft),r,rep);showInfo('<h2>回答と結果の記録</h2><textarea id="snapshot-record" readonly rows="13">'+esc(JSON.stringify(snap,null,2))+'</textarea>');};
 document.getElementById('view-pdf').onclick=async()=>{const b=document.getElementById('view-pdf'),tab=window.open('about:blank','_blank');b.disabled=true;try{const bytes=await PiraPdf.create(rep),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));pdfUrls.push(url);if(tab){tab.opener=null;tab.location.href=url;}else showInfo('<p><a href="'+url+'" target="_blank" rel="noopener">PDFを開く</a></p>');}catch(e){if(tab)tab.close();showInfo('<h2>PDFを開けませんでした</h2>');console.error(e);}finally{b.disabled=false;}};
}
function render(){if(state.screen==='start')landing();else if(state.screen==='question')question();else result();}
render();
})();
